/*
 * The library: one entry point (LVO -30) returning the dispatch table
 * (dispatch.auto.c, generated by oglesgen.py from the SDK's
 * ogles2_dispatch.h). docs/phase9-ogles2.md.
 */

extern const struct OGLES2Dispatch ogles2_dispatch;

void INIT_0_OGLES2(void) {
	glInit();
}

void EXIT_0_OGLES2(void) {
	glExit();
}

const struct OGLES2Dispatch *OGLES2GetDispatchTable(void) {
	return &ogles2_dispatch;
}

